# Malí (Sundiata) y Saladino. Mismas reglas que camp_vik_ing.py.

def R(tropas, donde="capital", jugador=0):
    # jugador None = el equipo enemigo (el primero que quede vivo del equipo 1)
    ref = {"tropas": tropas, "donde": donde}
    if jugador is None: ref["equipo"] = 1
    else: ref["jugador"] = jugador
    return {"refuerzos": ref}

